/* ================== KONFIGURASI ================== */
const WA_NUMBER = "6289662494592";            // 0896-6249-4592 (format internasional)
const SHOPEE_URL = "https://id.shp.ee/jERS7sGm";   // link toko Shopee DonatMini.co

const PRICE_PER_PCS = 3500;                   // harga satuan per 1 pcs (ubah di sini kalau berbeda)

// Harga bundling / tebus murah (urutan dari paket terbesar)
